	.file	"xpkSLZ3_lib.s"
	.text

/*
**	xpkSLZ3_lib.s -- resident module header for
**	xpkSLZ3.library 1.1 "SpeedLZ" (Speed Lempel-Ziv77).
**
**	Single code hunk; "moveq #-1,d0 / rts" entry stub; packed
**	RomTag (RTF_AUTOINIT, ver 1, NT_LIBRARY); InitTable with
**	dataSize 0x26 and a word-offset FUNCTABLE (generated by
**	genfunctab.py); LibInit stores the seglist at base+38.
**
**	Hunk map of the original (offset -> contents):
**	  0x00  moveq #-1,d0 / rts    entry stub
**	  0x04  RomTag                AUTOINIT, ver 1 (relocated
**				    match/endskip/name/idstr/init)
**	  0x1e  InitTable             dataSize 0x26
**	  0x2e  "xpkSLZ3.library" / "xpkSLZ3 1.1 (25.08.11)"
**	  0x58  functab               -1, 10 word offsets, -1
**	  0x70  datatab               flags 6, ver 1 rev 1
**	  0x90  LibInit               store seglist @38
**	  0x98  LibOpen / LibClose / LibExpunge
**	  0xea  null                  (also -42/-48/-60)
**	  0xee  XpksPackerInfo        lea descriptor 0x43a
**	  0xf6  XpksUnpackChunk       stream decoder
**	  0x13c ctxins                16-deep context LRU update
**	  0x1b2 XpksPackChunk         encoder (256KB ctx table)
**	  0x43a XpkInfo + XpkMode ("SpeedLZ") + strings
**	  0x59a nop; HUNK_RELOC32 x18; HUNK_END
*/

	.globl	_start
_start:
	moveq	#-1,%d0
	rts

	.globl	_romtag
_romtag:
	.word	0x4afc
	.long	_romtag
	.long	_endmodule
	.byte	0x80			/* RTF_AUTOINIT		    */
	.byte	1			/* RT_VERSION = 1	    */
	.byte	9			/* NT_LIBRARY		    */
	.byte	0			/* RT_PRI		    */
	.long	_libname
	.long	_idstr
	.long	_inittab

	.globl	_inittab
_inittab:
	.long	0x26			/* dataSize (seglist at +38
					   relies on AllocMem 8-byte
					   rounding: 38 -> 40)	    */
	.long	_functab
	.long	_datatab
	.long	_LibInit

_datatab:
	.byte	0xa0,0x08		/* ln_Type = 9		    */
	.byte	0x09,0x00
	.byte	0x80,0x0a		/* ln_Name		    */
	.long	_libname
	.byte	0xa0,0x0e		/* lib_Flags = 6	    */
	.byte	0x06,0x00
	.byte	0x90,0x14		/* version = 1		    */
	.word	0x0001
	.byte	0x90,0x16		/* revision = 1		    */
	.word	0x0001
	.byte	0x80,0x18		/* idstring		    */
	.long	_idstr
	.byte	0x00,0x00

_libname:
	.ascii	"xpkSLZ3.library"
	.byte	0
_idstr:
	.ascii	"xpkSLZ3 1.1 (25.08.11)"
	.byte	13,10,0

/*
**	LibInit -- a0 = seglist, d0 = libbase, a6 = execbase.
**	Stores the seglist at base+38 and returns the base in d0.
*/
	.globl	_LibInit
_LibInit:
	moveal	%d0,%a1
	movel	%a0,%a1@(38)		/* seglist		    */
	rts

/* ------------------------------------------------------------------ */
/* static XpkInfo descriptor (XpksPackerInfo returns its address)	    */
/* ------------------------------------------------------------------ */

	.even
	.globl	_xpkinfo
_xpkinfo:
	.word	1			/* xi_XpkInfoVersion	    */
	.word	1			/* xi_LibVersion	    */
	.word	2			/* xi_MasterVersion	    */
	.word	0			/* xi_ModesVersion	    */
	.long	_s_name			/* xi_Name "SpeedLZ"	    */
	.long	_s_longname		/* xi_LongName		    */
	.long	_s_basedesc		/* xi_Description	    */
	.long	0x534c5a33		/* xi_ID = 'SLZ3'	    */
	.long	0x8009			/* xi_Flags		    */
	.long	0x7fffffff		/* xi_MaxPkInChunk	    */
	.long	15			/* xi_MinPkInChunk	    */
	.long	0x7fff			/* xi_DefPkInChunk	    */
	.long	_s_packmsg		/* xi_PackMsg		    */
	.long	_s_unpackmsg		/* xi_UnpackMsg		    */
	.long	_s_packedmsg		/* xi_PackedMsg		    */
	.long	_s_unpackedmsg		/* xi_UnpackedMsg	    */
	.word	100			/* xi_DefMode		    */
	.word	0			/* xi_Pad		    */
	.long	_s_xpkmode		/* xi_ModeDesc		    */
	.long	0,0,0,0,0,0		/* xi_Reserved		    */

/* XpkMode (42 bytes): the shipped pack/unpack memory fields say 1
 * although the packer really allocates 0x40002 bytes internally per
 * call; kept verbatim.						    */
_s_xpkmode:
	.long	0			/* xm_Next		    */
	.long	100			/* xm_Upto		    */
	.long	1			/* xm_Flags		    */
	.long	1			/* xm_PackMemory	    */
	.long	1			/* xm_UnpackMemory	    */
	.long	30			/* xm_PackSpeed	    */
	.long	600			/* xm_UnpackSpeed	    */
	.word	100			/* xm_Ratio		    */
	.word	0			/* xm_ChunkSize	    */
	.ascii	"SpeedLZ"
	.byte	0,0,0

_s_name:
	.ascii	"SpeedLZ"
	.byte	0
_s_longname:
	.ascii	"Speed Lempel-Ziv77 for graphics data and fast decompress"
	.byte	0
_s_basedesc:
	.ascii	"Based upon a workshop of Adisak Pochanayon 1993, all rights reserved"
	.byte	0
_s_packmsg:
	.ascii	"Lempel-Ziving"
	.byte	0
_s_unpackmsg:
	.ascii	"Unlempel-Ziving"
	.byte	0
_s_packedmsg:
	.ascii	"Lempel-Zived"
	.byte	0
_s_unpackedmsg:
	.ascii	"Unlempel-Zived"
	.byte	0
	.byte	0			/* pad to even		    */
